def schedule(jobs):
    # Sort jobs by end time without mutating the original list
    sorted_jobs = sorted(jobs, key=lambda x: x[1])
    n = len(sorted_jobs)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        start, end, profit = sorted_jobs[i-1]
        # Binary search for the rightmost job that ends <= start
        lo, hi = 0, i-2
        best = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if sorted_jobs[mid][1] <= start:
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        if best != -1:
            current_profit = profit + dp[best+1]
        else:
            current_profit = profit
        dp[i] = max(dp[i-1], current_profit)
    return dp[n]

